export type CollectionComponentEvidence={requirement:string;brand:string;line:string;vitola:string;sourceUrl?:string;sourceLabel?:string};
export type CollectionTemplate={templateId:string;name:string;aliases?:string[];presentationAliases?:string[];maker:string;releaseYear?:number;edition?:string;expectedComponents:number;expectedIdentities?:number;expectedCigars?:number;requirements:string[];componentEvidence?:CollectionComponentEvidence[];packaging:string;releaseQuantity?:string;matchingRule:string;imageUrl?:string;imageSourceUrl?:string;imageSourceLabel?:string;accent:string;sourceUrl:string;sourceLabel:string;documentedWholeValue?:number;valueAsOf?:string;researchStatus:"Verified"|"Needs component detail"};
const incompleteVitola=/^(size|vitola|identity)\s+to\s+verify$|^(unknown|unspecified|n\/a|tbd)$/i;
const normalizedEvidencePart=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
export function completeCollectionComponentEvidence(component:CollectionComponentEvidence|undefined){
 if(!component?.sourceUrl||!component.sourceLabel||!component.brand.trim()||!component.line.trim()||!component.vitola.trim())return false;
 if(incompleteVitola.test(component.vitola.trim()))return false;
 return normalizedEvidencePart(component.vitola)!==normalizedEvidencePart(component.line);
}
const presentationRequirement=/^(?:original|numbered|one of|included)\b.*\b(?:box|case|book|packaging|humidor|cutter|certificate)\b/i;
export function isCollectionPresentationRequirement(requirement:string){
 return presentationRequirement.test(requirement.trim());
}
const documentedRequirementQuantity=(requirement:string)=>{
 const numeric=requirement.match(/^(\d+)\s+/);
 if(numeric){
  const quantity=Number(numeric[1]);
  // Four-digit release years and numbered series at the start of a cigar
  // name are identity, not a physical quantity.
  if(quantity<=500)return quantity;
 }
 const word=requirement.match(/^(one|two|three|four|five|six|seven|eight|nine|ten)\b/i)?.[1]?.toLowerCase();
 const words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10} as const;
 return word?words[word as keyof typeof words]:1;
};
export type CollectionTemplateProtocolAudit={
 componentRequirements:string[];
 sourcedRequirements:string[];
 unresolvedRequirements:string[];
 expectedPhysicalLots:number;
 documentedPhysicalLots:number;
 expectedCigars?:number;
 documentedCigars:number;
 readyForInventoryAutomation:boolean;
 issues:string[];
};
/**
 * Universal acceptance protocol for current and future collections.
 * Incomplete templates remain visible for research, but cannot be treated as
 * proof for automatic collector-inventory creation, repair, or assignment.
 */
export function auditCollectionTemplateProtocol(template:CollectionTemplate):CollectionTemplateProtocolAudit{
 const componentRequirements=template.requirements.filter(requirement=>!isCollectionPresentationRequirement(requirement));
 const sourcedRequirements=componentRequirements.filter(requirement=>completeCollectionComponentEvidence(
  template.componentEvidence?.find(component=>component.requirement===requirement),
 ));
 const unresolvedRequirements=componentRequirements.filter(requirement=>!sourcedRequirements.includes(requirement));
 const documentedCigars=sourcedRequirements.reduce((sum,requirement)=>sum+documentedRequirementQuantity(requirement),0);
 const issues:string[]=[];
 if(template.expectedComponents!==componentRequirements.length)issues.push(`Expected ${template.expectedComponents} physical lots but ${componentRequirements.length} exact component requirements are listed.`);
 if(unresolvedRequirements.length)issues.push(`${unresolvedRequirements.length} component requirement${unresolvedRequirements.length===1?" lacks":"s lack"} attributable exact-vitola evidence.`);
 if(template.expectedCigars!==undefined&&documentedCigars!==template.expectedCigars)issues.push(`Documented sourced quantities total ${documentedCigars}, not ${template.expectedCigars}.`);
 if(/\bhumidor\b/i.test(template.packaging)&&!(template.presentationAliases?.length))issues.push("Presentation humidor aliases are not documented separately from cigar membership.");
 return{
  componentRequirements,
  sourcedRequirements,
  unresolvedRequirements,
  expectedPhysicalLots:template.expectedComponents,
  documentedPhysicalLots:sourcedRequirements.length,
  expectedCigars:template.expectedCigars,
  documentedCigars,
  readyForInventoryAutomation:issues.length===0,
  issues,
 };
}
